fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    // Initialize with the first element of the prefix
    let mut max_value = v[0];
    let mut max_idx = 0;
    // Iterate from index 1 up to and including `end`
    for i in 1..=end {
        if v[i] > max_value {
            max_value = v[i];
            max_idx = i;
        }
    }
    (max_value, max_idx)
}

fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    // Initialize with the first element of the suffix
    let mut min_value = v[start];
    let mut min_idx = start;
    // Iterate from `start + 1` to the end of the slice
    for i in (start + 1)..v.len() {
        if v[i] < min_value {
            min_value = v[i];
            min_idx = i;
        }
    }
    (min_value, min_idx)
}

fn barrier(v: &[i32], p: usize) -> bool {
    // If `p` is the last index, there's no suffix to compare to; return true.
    if p + 1 >= v.len() {
        return true;
    }
    // Find the maximum in v[0..=p]
    let (max_pref, _) = find_max_in_prefix(v, p);
    // Find the minimum in v[p+1..]
    let (min_suf, _) = find_min_in_suffix(v, p + 1);
    // The barrier holds if and only if max_pref < min_suf
    max_pref < min_suf
}

